<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {api,errorText} from '../../api/zenflow/client';
interface User{id:string;publicId:string;displayName:string;email:string|null;state:string;version:number;createdAt:string;loginMethods:string[];membershipState:string;lastLoginAt:string|null;loginCount:number;activeSeconds:number;lastActiveAt:string|null;inputTokens:number;outputTokens:number;totalTokens:number;modelRuns:number;measuredRuns:number;partialRuns:number}
const rows=ref<User[]>([]),query=ref(''),state=ref('ALL'),loading=ref(false),busy=ref(''),cursor=ref<string|null>(null);
const billing=ref<User|null>(null);
const time=(value:string|null)=>value?new Date(value).toLocaleString():'尚未采集';
const duration=(seconds:number)=>seconds>=3600?`${(seconds/3600).toFixed(1)} 小时`:seconds>=60?`${Math.floor(seconds/60)} 分钟`:`${seconds} 秒`;
const tokens=(user:User)=>user.modelRuns>0&&!user.measuredRuns?'尚未采集':Number(user.totalTokens).toLocaleString();
let request=0;
async function load(more=false){const ticket=++request;loading.value=true;try{const {data}=await api.get('/users',{params:{query:query.value,state:state.value,limit:25,...(more&&cursor.value?{before:cursor.value}:{})}});if(ticket!==request)return;rows.value=more?[...rows.value,...data.items]:data.items;cursor.value=data.hasMore?data.nextCursor:null;}catch(e){ElMessage.error(errorText(e));}finally{if(ticket===request)loading.value=false;}}
async function change(user:User){const target=user.state==='ACTIVE'?'DISABLED':'ACTIVE';try{await ElMessageBox.confirm(target==='DISABLED'?'停用后该用户无法登录，现有会话权限也会失效。':'启用后该用户需要重新登录。',`${target==='DISABLED'?'停用':'启用'} ${user.displayName||user.publicId}`,{confirmButtonText:'确认',cancelButtonText:'取消',type:'warning'});}catch{return;}busy.value=user.id;try{await api.post(`/users/${user.id}/state`,{state:target,expectedVersion:user.version});ElMessage.success('账号状态已更新');await load();}catch(e){ElMessage.error(errorText(e));}finally{busy.value='';}}
onMounted(()=>load());
</script>
<template><section><div class="page-heading"><div><div class="eyebrow">PEOPLE</div><h1>用户管理</h1><p class="muted">管理账号身份与使用状态，个人对话和记录保持私有。</p></div><el-button :loading="loading" @click="load()">刷新</el-button></div><div class="actions"><el-input v-model="query" clearable placeholder="搜索昵称、邮箱或公开编号" maxlength="64" style="max-width:320px" @keyup.enter="load()"/><el-select v-model="state" style="width:150px" @change="load()"><el-option label="全部状态" value="ALL"/><el-option label="正常使用" value="ACTIVE"/><el-option label="已停用" value="DISABLED"/></el-select><el-button :disabled="loading" @click="load()">搜索</el-button></div><el-table v-loading="loading" :data="rows" empty-text="暂无匹配用户" style="margin-top:20px"><el-table-column label="用户" min-width="200"><template #default="{row}"><strong>{{row.displayName||'未设置昵称'}}</strong><div class="muted" style="font-size:12px">{{row.email||'尚未提供邮箱'}}</div></template></el-table-column><el-table-column prop="email" label="邮箱" min-width="200"/><el-table-column label="登录方式" min-width="130"><template #default="{row}">{{row.loginMethods.join(' / ')||'—'}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.state==='ACTIVE'?'success':'info'">{{row.state==='ACTIVE'?'正常':'已停用'}}</el-tag></template></el-table-column><el-table-column label="最近登录" min-width="175"><template #default="{row}">{{time(row.lastLoginAt)}}<div class="muted">{{row.loginCount}} 次已采集登录</div></template></el-table-column><el-table-column label="活跃使用时长" min-width="135"><template #default="{row}">{{duration(row.activeSeconds)}}<div class="muted">前台心跳估算</div></template></el-table-column><el-table-column label="模型 token" min-width="150"><template #default="{row}">{{tokens(row)}}<div class="muted">{{row.measuredRuns}} / {{row.modelRuns}} 轮有用量</div></template></el-table-column><el-table-column label="会员" width="120"><template #default>设计预留</template></el-table-column><el-table-column label="操作" width="160"><template #default="{row}"><el-button text :type="row.state==='ACTIVE'?'danger':'primary'" :disabled="!!busy" :loading="busy===row.id" @click="change(row)">{{row.state==='ACTIVE'?'停用':'启用'}}</el-button><el-button text type="primary" @click="billing=row">用量 / 账单</el-button></template></el-table-column></el-table><el-button v-if="cursor" style="margin-top:16px" :disabled="loading" @click="load(true)">更多用户</el-button><p class="muted">时长来自登录后的前台心跳；后台、离线及采集上线前的时间不补估。Token 使用供应商回传数值，包含本轮上下文浓缩；历史缺失用量不当作 0。时间按浏览器本地时区显示。</p><el-drawer :model-value="!!billing" :title="billing?`${billing.displayName} · 用量与账单`:''" size="min(560px,94vw)" @close="billing=null"><template v-if="billing"><el-descriptions :column="1" border><el-descriptions-item label="用户">{{billing.displayName}}</el-descriptions-item><el-descriptions-item label="公开编号">{{billing.publicId}}</el-descriptions-item><el-descriptions-item label="注册时间">{{time(billing.createdAt)}}</el-descriptions-item><el-descriptions-item label="最近登录">{{time(billing.lastLoginAt)}}</el-descriptions-item><el-descriptions-item label="最近活跃">{{time(billing.lastActiveAt)}}</el-descriptions-item><el-descriptions-item label="累计前台时长">{{duration(billing.activeSeconds)}}</el-descriptions-item><el-descriptions-item label="输入 token">{{Number(billing.inputTokens).toLocaleString()}}</el-descriptions-item><el-descriptions-item label="输出 token">{{Number(billing.outputTokens).toLocaleString()}}</el-descriptions-item><el-descriptions-item label="采集覆盖">{{billing.measuredRuns}} / {{billing.modelRuns}} 轮；{{billing.partialRuns}} 轮仅有部分用量</el-descriptions-item></el-descriptions><h2 style="margin-top:24px">会员与账单 · 设计预留</h2><p class="muted">后续账单关联该用户的公开编号和实际模型用量。试用天数、会员套餐、币种与费率待确认。</p><el-empty description="账单与支付尚未启用" :image-size="80"/><p class="muted">未生成收费账单，也不将供应商 token 用量直接当作用户应付费用。</p></template></el-drawer></section></template>
